import csv
import io


def parse_csv(raw_csv: str):
    expected_width = 2
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )
    records = list(reader)

    def normalize(record):
        values = list(record)
        if len(values) > expected_width:
            values = values[: expected_width - 1] + [",".join(values[expected_width - 1 :])]
        else:
            values.extend([""] * (expected_width - len(values)))
        return values

    if not records:
        return {"columns": ["", ""], "rows": []}

    header_index = next(
        (i for i, record in enumerate(records) if len(record) == expected_width),
        0,
    )
    columns = normalize(records[header_index])
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    # Preserve any leading preamble records as rows, along with every record after the header.
    data_records = records[:header_index] + records[header_index + 1 :]
    rows = [normalize(record) for record in data_records]

    return {"columns": columns, "rows": rows}
